   642	\begin{lemma}[Removing the $X$-point factor]
   643		\label{lem:claim-17-2}
   644		% claim:17-2 in the paper; the original label is recorded here as a
   645		% comment for cross-reference fidelity. The source right-hand side
   646		% carries a typographical superscript "Z" in place of the point "z";
   647		% the corrected form is stated here.
   648		\uses{lem:qld-sublines, lem:qld-xz-lines,
   649			def:expanded-point-measurement, lem:qld-comm-line-cons,
   650			def:expanded-state}
   651		\begin{align*}
   652			\E_{(\ell,\ell_X,\ell_Z) \sim D}\
   653			\E_{(x,z,\alpha,\beta) \in \ell}
   654			&\sum_{f_X,f_Z} \bra{\hat\psi}
   655			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
   656			\big(\hat{M}^{(\mathrm{Point},Z),z}_{f_Z(z)} \,
   657			\hat{M}^{(\mathrm{Point},X),x}_{f_X(x)}
   658			\big)_{\mathsf{B}\mathsf{A}''}
   659			\ket{\hat\psi} \\
   660			\approx_{m\,\delta_{\mathrm{Line}}^{1/2}}\
   661			\E_{(\ell,\ell_X,\ell_Z) \sim D}\
   662			\E_{(x,z,\alpha,\beta) \in \ell}
   663			&\sum_{f_X,f_Z} \bra{\hat\psi}
   664			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
   665			\big(\hat{M}^{(\mathrm{Point},Z),z}_{f_Z(z)}
   666			\big)_{\mathsf{B}\mathsf{A}''}
   667			\ket{\hat\psi}\,,
   668		\end{align*}
   669		where $\delta_{\mathrm{Line}}$ is the error function of
   670		Lemma~\ref{lem:qld-comm-line-cons}.
   671	\end{lemma}
   672	\begin{proof}
   673		\uses{lem:qld-comm-line-cons, lem:qld-sublines,
   674			lem:restricted-line-mixture-bounds, def:ith-restricted-line,
   675			def:expanded-line-measurement}
   676		By Cauchy--Schwarz, the difference of the two sides is bounded by the
   677		square root of the deficit
   678		\[
   679			1 - \E_{(\ell,\ell_X,\ell_Z) \sim D}\
   680			\E_{(x,z,\alpha,\beta) \in \ell} \sum_{a}
   681			\bra{\hat\psi}
   682			T^{\ell_X,\ell_Z,x}_{a} \ot
   683			\hat{M}^{(\mathrm{Point},X),x}_{a}
   684			\ket{\hat\psi}\,,
   685			\qquad
   686			T^{\ell_X,\ell_Z,x}_{a}
   687			= \sum_{f_X,f_Z \,:\, f_X(x)=a}
   688			T^{\ell_X,\ell_Z}_{f_X,f_Z}\,.
   689		\]
   690		By the sandwich definition of $T$ and the projectivity of the lines
   691		measurement $\{\hat{M}^{(\mathrm{Line},X),\ell_X}_{f_X}\}$, the
   692		subtracted expectation equals
   693		$\E \sum_a \bra{\hat\psi}
   694		\hat{M}^{(\mathrm{Line},X),\ell_X}_{[\mathrm{eval}_x(\cdot)=a]} \ot
   695		\hat{M}^{(\mathrm{Point},X),x}_{a} \ket{\hat\psi}$,
   696		which by Property~2 of Lemma~\ref{lem:qld-sublines} is a mixture of the
   697		corresponding averages over the restricted distributions
   698		$D_{\mathrm{v},i}$. By the error inflation of
   699		Lemma~\ref{lem:restricted-line-mixture-bounds} applied to the
   700		line--point consistency in item~3 of Lemma~\ref{lem:qld-comm-line-cons},
   701		each restricted term has deficit $O(m\,\delta_{\mathrm{Line}})$, so the
   702		total deficit is $O(m^2\,\delta_{\mathrm{Line}})$ (the final line of the
   703		source proof asserts this bound for the consistency term itself rather
   704		than for its deficit; see Remark~\ref{rem:qld-4-13-source-defects}).
   705		Taking the square root gives the claimed error
   706		$m\,\delta_{\mathrm{Line}}^{1/2}$.
   707	\end{proof}
