   729			lem:qld-xz-lines, lem:qld-4-10, lem:qld-comm-cons,
   730			def:ith-restricted-line}
   731		By Cauchy--Schwarz it suffices to bound the deficit
   732		$1 - \E \sum_b \bra{\hat\psi} T^{\ell_X,\ell_Z,z}_{b} \ot
   733		\hat{M}^{(\mathrm{Point},Z),z}_{b} \ket{\hat\psi}$,
