   767	\begin{proof}[Proof of Lemma~\ref{lem:qld-4-13}]
   768		\proves{lem:qld-4-13}
   769		\uses{lem:qld-xz-lines, lem:qld-sublines, def:combine-map,
   770			lem:qld-4-12, lem:claim-17-1, lem:claim-17-2, lem:claim-17-3,
   771			lem:restricted-line-mixture-bounds}
   772		Let $D$ be the distribution of Lemma~\ref{lem:qld-sublines} and let
   773		$D_{|\ell}$ denote $D$ conditioned on the first element being $\ell$.
   774		For every line $\ell$ in $\F_q^{2m+2}$ and $f \in \deg_{md+1}(\ell)$
   775		define
   776		\[
   777			\hat{Q}^{\ell}_{f}
   778			= \E_{(\ell_X,\ell_Z) \sim D_{|\ell}}
   779			\sum_{\substack{f_X \in \deg_{md}(\ell_X),\
   780				f_Z \in \deg_{md}(\ell_Z):\\
   781				f = \mathrm{combine}_{f_X,f_Z}}}
   782			T^{\ell_X,\ell_Z}_{f_X,f_Z}\,,
   783		\]
   784		a valid POVM; the polynomial $\mathrm{combine}_{f_X,f_Z}$ of
   785		Definition~\ref{def:combine-map} is well defined here because Property~2
   786		of Lemma~\ref{lem:qld-sublines} guarantees that $\ell_X$ and $\ell_Z$
   787		are compatible with $\ell$. If $\ell$ is axis-parallel, then by
   788		Property~3 of Lemma~\ref{lem:qld-sublines} so are $\ell_X$ and
   789		$\ell_Z$, hence $f_X, f_Z \in \deg_d$ by Lemma~\ref{lem:qld-xz-lines};
   790		along such a line either $(\alpha,\beta)$ is constant, in which case
   791		$f = \mathrm{combine}_{f_X,f_Z}$ is a fixed linear combination of
   792		polynomials of degree at most $d$, or $(x,z)$ is constant, in which case
   793		$f$ is affine in the line parameter, so in either case
   794		$f \in \deg_d(\ell)$. Chaining Lemmas~\ref{lem:claim-17-1},
   795		\ref{lem:claim-17-2} and~\ref{lem:claim-17-3} with the triangle
   796		inequality for scalars gives the consistency bound
   797		\begin{equation}
   798			\label{eq:qld-combined-lines-consistency}
   799			\E_{(\ell,\ell_X,\ell_Z) \sim D}\
   800			\E_{(x,z,\alpha,\beta) \in \ell}
   801			\sum_{f_X,f_Z} \bra{\hat\psi}
   802			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
   803			\big(\Id - \hat{Q}^{x,z}_{f_X(x),f_Z(z)}
   804			\big)_{\mathsf{B}\mathsf{A}''}
   805			\ket{\hat\psi}
   806			= O\big(m\,(\eps^{1/4} + \delta_P^{1/4} + \delta_Q^{1/4}
   807			+ \delta_{\mathrm{Line}}^{1/2})\big)\,;
   808		\end{equation}
   809		alternatively, by Property~2 of Lemma~\ref{lem:qld-sublines} the
   810		left-hand side of \eqref{eq:qld-combined-lines-consistency} is a mixture
   811		of restricted-distribution terms, each bounded by
   812		\eqref{eq:qld-xz-lines-restricted}, which gives the bound
   813		$O(m^2 \delta_P)$ for the same quantity (see
   814		Remark~\ref{rem:qld-4-13-source-defects}); the function
   815		$\delta_{\mathrm{combine}} = \poly(m^2\eps, md/q)$ dominates both. Now
   816		if the pair $(f_X, f_Z)$ evaluates to $(a, b)$ at $(x, z)$, then
   817		$\mathrm{combine}_{f_X,f_Z}$ evaluates to $\alpha a + \beta b$ at
   818		$(x, z, \alpha, \beta)$; hence the consistency of $T$ with
   819		$\hat{Q}^{x,z}$ along the sub-line pairs expressed by
   820		\eqref{eq:qld-combined-lines-consistency}, the definition of
   821		$\hat{Q}^{\ell}$ as the image of $T$ under the combining map, and the
   822		construction of $\hat{Q}^{x,z,\alpha,\beta}$ in
   823		Lemma~\ref{lem:qld-4-12} as the corresponding coarse-graining of
   824		$\hat{Q}^{x,z}$ together yield the first relation of
   825		\eqref{eq:qld-4-13}. The second relation follows from the analogous
   826		argument with the registers swapped.
   827	\end{proof}
